"""Master materials, generated by script so the plugin ships no binary assets.

One master per blend mode (opaque / masked / translucent). Every Blender material
becomes a Material Instance of one of them.

Parameters
  BaseColor (vector, tint)  BaseColorTex + UseBaseColorTex
  UseColorAdjust            ColorGain / ColorLift (brightness-contrast), HueShift, Saturation, ColorValue
  UseAOTex                  AOTex + AOChannel + AOStrength (AO multiplied into base colour, like Blender)
  Metallic / Roughness      <X>Tex + <X>Channel (RGBA mask) + <X>Invert + Use<X>Tex
  Specular (scalar)
  NormalTex + NormalStrength + UseNormalTex
  EmissiveColor / EmissiveStrength, EmissiveTex + UseEmissiveTex
  Alpha, AlphaTex + AlphaChannel + UseAlphaTex, AlphaFromBaseColorTex   (masked / translucent)
  UVTiling / UVOffset (vector, XY used)
  Coat / CoatRoughness      used when the instance switches its shading model to Clear Coat
  SubsurfaceColor / SubsurfaceOpacity   opaque + masked, used with the Subsurface shading model
  IOR, GlassFresnel + GlassOpacity      translucent only: refraction, and see-through that fades at grazing angles
"""
import os

import unreal

from .util import Log, asset_tools, exists, load, set_prop

MASTER_DIR = "/Game/BlenderBridge/Masters"
VERSION = 5
KINDS = {
    "opaque": ("Opaque", "BLEND_OPAQUE"),
    "masked": ("Masked", "BLEND_MASKED"),
    "translucent": ("Translucent", "BLEND_TRANSLUCENT"),
}
mel = unreal.MaterialEditingLibrary
LINEAR_WHITE = MASTER_DIR + "/T_BB_LinearWhite"


def ensure_linear_white(log):
    """The engine checks a parameter's sampler type against its DEFAULT texture, so the
    linear (data) parameters need a linear default. We ship a tiny one."""
    tex = load(LINEAR_WHITE)
    if tex is None:
        t = unreal.AssetImportTask()
        t.filename = os.path.join(os.path.dirname(__file__), "resources", "T_BB_LinearWhite.png")
        t.destination_path, t.destination_name = MASTER_DIR, "T_BB_LinearWhite"
        t.automated, t.replace_existing, t.save = True, True, False
        asset_tools().import_asset_tasks([t])
        tex = load(LINEAR_WHITE)
        if tex is None:
            raise RuntimeError("could not import the default linear texture")
    if tex.get_editor_property("srgb"):
        tex.set_editor_property("srgb", False)
        unreal.EditorAssetLibrary.save_loaded_asset(tex)
    return tex



FEATURES = {"MP_CUSTOM_DATA0": "clear coat", "MP_CUSTOM_DATA1": "clear coat roughness",
            "MP_REFRACTION": "glass refraction", "MP_SUBSURFACE_COLOR": "subsurface colour"}


def material_property(name):
    """unreal.MaterialProperty member by name, tolerant of how the engine spells it
    (MP_CUSTOM_DATA0 / MP_CUSTOMDATA0 / ...). None if the engine doesn't offer it."""
    enum = unreal.MaterialProperty
    if hasattr(enum, name):
        return getattr(enum, name)
    want = name.replace("_", "").lower()
    for attr in dir(enum):
        if attr.replace("_", "").lower() == want:
            return getattr(enum, attr)
    return None


def master_path(kind):
    return f"{MASTER_DIR}/M_BB_{KINDS[kind][0]}_v{VERSION}"


def ensure_master(kind, log):
    path = master_path(kind)
    return load(path) or _build(kind, log)


def rebuild_masters():
    log = Log()
    for kind in KINDS:
        path = master_path(kind)
        if exists(path):
            unreal.EditorAssetLibrary.delete_asset(path)
        _build(kind, log)
    unreal.EditorAssetLibrary.save_directory(MASTER_DIR, only_if_is_dirty=True, recursive=True)
    log.info("master materials rebuilt")


class _Graph:
    def __init__(self, mat, log):
        self.mat, self.log = mat, log

    def node(self, cls_name, x, y, **props):
        n = mel.create_material_expression(self.mat, getattr(unreal, cls_name), x, y)
        for k, v in props.items():
            set_prop(n, k, v, self.log)
        return n

    def link(self, src, out, dst, *inputs):
        """Connect src.out -> dst.<first input name that works>."""
        for name in inputs:
            try:
                if mel.connect_material_expressions(src, out, dst, name):
                    return True
            except Exception:
                pass
        self.log.warn(f"master material: could not connect {type(src).__name__} -> "
                      f"{type(dst).__name__}.{inputs[0]}")
        return False

    def out(self, src, out, prop_name):
        prop = material_property(prop_name)
        if prop is None:      # not offered by this engine version: skip that feature, keep building
            self.log.warn(f"master material: this engine has no '{prop_name}' output, so "
                          f"{FEATURES.get(prop_name, 'that input')} is left out")
            return
        if not mel.connect_material_property(src, out, prop):
            self.log.warn(f"master material: could not connect {prop_name}")

    # small helpers -------------------------------------------------------
    def scalar(self, name, default, x, y):
        return self.node("MaterialExpressionScalarParameter", x, y, parameter_name=name, default_value=default)

    def vector(self, name, rgba, x, y):
        return self.node("MaterialExpressionVectorParameter", x, y, parameter_name=name,
                         default_value=unreal.LinearColor(*rgba))

    def binary(self, cls, a, a_out, b, b_out, x, y):
        n = self.node(cls, x, y)
        self.link(a, a_out, n, "A")
        self.link(b, b_out, n, "B")
        return n

    def rgba(self, n, x, y):
        """float4 from a node with RGB (first) and A outputs."""
        return self.binary("MaterialExpressionAppendVector", n, "", n, "A", x, y)

    def switch(self, name, true_node, false_node, x, y, true_out="", false_out=""):
        sw = self.node("MaterialExpressionStaticSwitchParameter", x, y, parameter_name=name, default_value=False)
        self.link(true_node, true_out, sw, "True", "A")
        self.link(false_node, false_out, sw, "False", "B")
        return sw

    def texture(self, name, sampler, uv, x, y, default=None):
        t = self.node("MaterialExpressionTextureSampleParameter2D", x, y, parameter_name=name)
        if default:
            tex = unreal.load_asset(default)
            if tex:
                set_prop(t, "texture", tex, self.log)
        set_prop(t, "sampler_type", getattr(unreal.MaterialSamplerType, sampler), self.log)
        self.link(uv, "", t, "UVs", "Coordinates")
        return t

    def masked_scalar(self, prefix, default, uv, x, y):
        """Use<prefix>Tex ? dot(tex.rgba, <prefix>Channel) * value : value"""
        val = self.scalar(prefix, default, x, y)
        tex = self.texture(prefix + "Tex", "SAMPLERTYPE_LINEAR_COLOR", uv, x, y + 80, default=LINEAR_WHITE)
        mask = self.vector(prefix + "Channel", (1, 0, 0, 0), x, y + 300)
        dot = self.binary("MaterialExpressionDotProduct", self.rgba(tex, x + 250, y + 80), "",
                          self.rgba(mask, x + 250, y + 300), "", x + 450, y + 150)
        inv = self.node("MaterialExpressionOneMinus", x + 450, y + 300)
        self.link(dot, "", inv, "", "Input")
        pick = self.node("MaterialExpressionLinearInterpolate", x + 600, y + 220)
        self.link(dot, "", pick, "A")
        self.link(inv, "", pick, "B")
        self.link(self.scalar(prefix + "Invert", 0.0, x + 450, y + 400), "", pick, "Alpha")
        mul = self.binary("MaterialExpressionMultiply", pick, "", val, "", x + 750, y + 80)
        return self.switch("Use" + prefix + "Tex", mul, val, x + 950, y)


def _build(kind, log):
    """Build a master material. All or nothing: if anything fails the half-built asset is deleted,
    so it is never saved and reused."""
    ensure_linear_white(log)
    suffix, blend = KINDS[kind]
    name = f"M_BB_{suffix}_v{VERSION}"
    mat = asset_tools().create_asset(name, MASTER_DIR, unreal.Material, unreal.MaterialFactoryNew())
    if mat is None:
        raise RuntimeError(f"could not create master material {MASTER_DIR}/{name}")
    try:
        return _fill(mat, kind, blend, name, log)
    except Exception:
        unreal.EditorAssetLibrary.delete_asset(f"{MASTER_DIR}/{name}")
        raise


def _fill(mat, kind, blend, name, log):
    set_prop(mat, "blend_mode", getattr(unreal.BlendMode, blend), log)
    if kind == "translucent":
        modes = unreal.TranslucencyLightingMode     # per-pixel lighting gives glass its highlights
        mode = getattr(modes, "TLM_SURFACE_PER_PIXEL_LIGHTING", None) or getattr(modes, "TLM_SURFACE", None)
        if mode is not None:
            set_prop(mat, "translucency_lighting_mode", mode)
    g = _Graph(mat, log)

    # UVs = TexCoord * UVTiling.xy + UVOffset.xy
    tc = g.node("MaterialExpressionTextureCoordinate", -2600, 0)
    til = g.node("MaterialExpressionComponentMask", -2400, 150, r=True, g=True, b=False, a=False)
    g.link(g.vector("UVTiling", (1, 1, 0, 0), -2650, 150), "", til, "", "Input")
    off = g.node("MaterialExpressionComponentMask", -2400, 400, r=True, g=True, b=False, a=False)
    g.link(g.vector("UVOffset", (0, 0, 0, 0), -2650, 400), "", off, "", "Input")
    uv = g.binary("MaterialExpressionAdd",
                  g.binary("MaterialExpressionMultiply", tc, "", til, "", -2200, 50), "", off, "", -2050, 150)

    # Base colour: tex -> (brightness/contrast -> saturation -> hue -> value) -> * tint -> * AO
    x = -1700
    tint = g.vector("BaseColor", (0.8, 0.8, 0.8, 1), x, -900)
    base_tex = g.texture("BaseColorTex", "SAMPLERTYPE_COLOR", uv, x, -700)
    ax, ay = x - 300, -2100
    zero = g.node("MaterialExpressionConstant", ax, ay + 500, r=0.0)
    one = g.node("MaterialExpressionConstant", ax, ay + 560, r=1.0)
    bc = g.binary("MaterialExpressionAdd",
                  g.binary("MaterialExpressionMultiply", base_tex, "", g.scalar("ColorGain", 1.0, ax, ay), "",
                           ax + 250, ay), "", g.scalar("ColorLift", 0.0, ax, ay + 100), "", ax + 400, ay)
    bc = g.binary("MaterialExpressionMax", bc, "", zero, "", ax + 550, ay)
    frac = g.node("MaterialExpressionOneMinus", ax + 550, ay + 200)
    g.link(g.scalar("Saturation", 1.0, ax, ay + 200), "", frac, "", "Input")
    desat = g.node("MaterialExpressionDesaturation", ax + 750, ay)
    g.link(bc, "", desat, "", "Input")
    g.link(frac, "", desat, "Fraction")
    # hue shift = rotate the colour about the grey axis (what the engine's HueShift function does)
    rot = g.node("MaterialExpressionRotateAboutAxis", ax + 1000, ay + 200, period=1.0)
    axis = g.node("MaterialExpressionConstant3Vector", ax + 750, ay + 300,
                  constant=unreal.LinearColor(0.57735, 0.57735, 0.57735, 0))
    pivot = g.node("MaterialExpressionConstant3Vector", ax + 750, ay + 500, constant=unreal.LinearColor(0, 0, 0, 0))
    g.link(axis, "", rot, "NormalizedRotationAxis")
    g.link(g.scalar("HueShift", 0.0, ax + 750, ay + 400), "", rot, "RotationAngle")
    g.link(pivot, "", rot, "PivotPoint")
    g.link(desat, "", rot, "Position")
    hued = g.binary("MaterialExpressionAdd", rot, "", desat, "", ax + 1250, ay)
    valued = g.binary("MaterialExpressionMultiply", hued, "", g.scalar("ColorValue", 1.0, ax + 1250, ay + 150), "",
                      ax + 1400, ay)
    adjusted = g.switch("UseColorAdjust", valued, base_tex, ax + 1600, ay + 100)
    base_mul = g.binary("MaterialExpressionMultiply", adjusted, "", tint, "", x + 300, -1000)
    ao_tex = g.texture("AOTex", "SAMPLERTYPE_LINEAR_COLOR", uv, x, -1500, default=LINEAR_WHITE)
    ao_mask = g.vector("AOChannel", (1, 0, 0, 0), x, -1300)
    ao = g.binary("MaterialExpressionDotProduct", g.rgba(ao_tex, x + 250, -1500), "",
                  g.rgba(ao_mask, x + 250, -1300), "", x + 450, -1400)
    ao_lerp = g.node("MaterialExpressionLinearInterpolate", x + 600, -1400)
    g.link(one, "", ao_lerp, "A")
    g.link(ao, "", ao_lerp, "B")
    g.link(g.scalar("AOStrength", 1.0, x + 450, -1250), "", ao_lerp, "Alpha")
    with_ao = g.switch("UseAOTex", g.binary("MaterialExpressionMultiply", base_mul, "", ao_lerp, "", x + 800, -1300),
                       base_mul, x + 1000, -1150)
    g.out(g.switch("UseBaseColorTex", with_ao, tint, x + 1250, -900), "", "MP_BASE_COLOR")

    # Metallic / Specular / Roughness
    g.out(g.masked_scalar("Metallic", 0.0, uv, x, -400), "", "MP_METALLIC")
    g.out(g.scalar("Specular", 0.5, x + 800, 100), "", "MP_SPECULAR")
    g.out(g.masked_scalar("Roughness", 0.5, uv, x, 200), "", "MP_ROUGHNESS")

    # Emissive
    em_col = g.vector("EmissiveColor", (0, 0, 0, 1), x, 800)
    em_tex = g.texture("EmissiveTex", "SAMPLERTYPE_COLOR", uv, x, 1000)
    em_sw = g.switch("UseEmissiveTex", em_tex, em_col, x + 400, 800)
    em_str = g.scalar("EmissiveStrength", 1.0, x + 400, 1000)
    g.out(g.binary("MaterialExpressionMultiply", em_sw, "", em_str, "", x + 800, 850), "", "MP_EMISSIVE_COLOR")

    # Normal = lerp(flat, tex, NormalStrength)
    flat = g.node("MaterialExpressionConstant3Vector", x, 1350, constant=unreal.LinearColor(0, 0, 1, 0))
    n_tex = g.texture("NormalTex", "SAMPLERTYPE_NORMAL", uv, x, 1500,
                      default="/Engine/EngineMaterials/DefaultNormal")
    n_str = g.scalar("NormalStrength", 1.0, x, 1750)
    lerp = g.node("MaterialExpressionLinearInterpolate", x + 400, 1450)
    g.link(flat, "", lerp, "A")
    g.link(n_tex, "", lerp, "B")
    g.link(n_str, "", lerp, "Alpha")
    g.out(g.switch("UseNormalTex", lerp, flat, x + 800, 1400), "", "MP_NORMAL")

    # Clear coat inputs (only read when an instance overrides the shading model to Clear Coat)
    g.out(g.scalar("Coat", 0.0, x + 800, 2700), "", "MP_CUSTOM_DATA0")
    g.out(g.scalar("CoatRoughness", 0.03, x + 800, 2800), "", "MP_CUSTOM_DATA1")

    # Opacity
    final = None
    if kind != "opaque":
        alpha = g.masked_scalar("Alpha", 1.0, uv, x, 2000)
        alpha_val = g.scalar("AlphaScale", 1.0, x + 800, 2300)
        from_base = g.binary("MaterialExpressionMultiply", base_tex, "A", alpha_val, "", x + 1000, 2200)
        final = g.switch("AlphaFromBaseColorTex", from_base, alpha, x + 1200, 2000)
    if kind == "masked":
        g.out(final, "", "MP_OPACITY_MASK")
    if kind == "translucent":
        # Glass: mostly see-through facing the camera, more reflective / opaque at grazing angles.
        fresnel = g.node("MaterialExpressionFresnel", x + 1200, 2500)
        glass = g.node("MaterialExpressionLinearInterpolate", x + 1400, 2450)
        g.link(g.scalar("GlassOpacity", 0.1, x + 1200, 2400), "", glass, "A")
        g.link(g.node("MaterialExpressionConstant", x + 1200, 2700, r=1.0), "", glass, "B")
        g.link(fresnel, "", glass, "Alpha")
        g.out(g.switch("GlassFresnel", glass, final, x + 1600, 2200), "", "MP_OPACITY")
        g.out(g.scalar("IOR", 1.0, x + 1600, 2600), "", "MP_REFRACTION")
    else:
        # Subsurface (only read when an instance overrides the shading model to Subsurface)
        g.out(g.vector("SubsurfaceColor", (1.0, 0.2, 0.1, 1), x + 800, 2950), "", "MP_SUBSURFACE_COLOR")
        g.out(g.scalar("SubsurfaceOpacity", 1.0, x + 800, 3150), "", "MP_OPACITY")

    mel.layout_material_expressions(mat)
    mel.recompile_material(mat)
    unreal.EditorAssetLibrary.save_loaded_asset(mat)
    log.info(f"built master material {name}")
    return mat


# --------------------------------------------------------------------------- sky dome
def build_sky_material(path, cubemap, color, intensity, rotation, log):
    """Unlit 'Is Sky' material for the sky dome: an HDRI cubemap (or a flat colour) times Intensity.
    Built per scene with the cubemap wired in directly, so the sampler type always matches it.
    Parameters: Intensity, Rotation (0..1 = one full turn), Color."""
    folder, name = path.rsplit("/", 1)
    mat = load(path)
    if mat is None:
        mat = asset_tools().create_asset(name, folder, unreal.Material, unreal.MaterialFactoryNew())
    else:
        mel.delete_all_material_expressions(mat)
    if mat is None:
        raise RuntimeError(f"could not create sky material {path}")
    set_prop(mat, "shading_model", unreal.MaterialShadingModel.MSM_UNLIT, log)
    set_prop(mat, "two_sided", True, log)
    set_prop(mat, "is_sky", True, log)
    g = _Graph(mat, log)
    strength = g.scalar("Intensity", float(intensity), -400, 300)
    if cubemap is not None:
        cam = g.node("MaterialExpressionCameraVectorWS", -1500, 0)
        minus = g.node("MaterialExpressionConstant", -1500, 150, r=-1.0)
        view = g.binary("MaterialExpressionMultiply", cam, "", minus, "", -1300, 0)   # camera -> sky
        rot = g.node("MaterialExpressionRotateAboutAxis", -1000, 150, period=1.0)
        g.link(g.node("MaterialExpressionConstant3Vector", -1300, 200, constant=unreal.LinearColor(0, 0, 1, 0)),
               "", rot, "NormalizedRotationAxis")
        g.link(g.scalar("Rotation", float(rotation), -1300, 350), "", rot, "RotationAngle")
        g.link(g.node("MaterialExpressionConstant3Vector", -1300, 450, constant=unreal.LinearColor(0, 0, 0, 0)),
               "", rot, "PivotPoint")
        g.link(view, "", rot, "Position")
        direction = g.binary("MaterialExpressionAdd", rot, "", view, "", -800, 0)
        tex = g.node("MaterialExpressionTextureSample", -600, 0)
        set_prop(tex, "texture", cubemap, log)      # sampler type follows the texture
        g.link(direction, "", tex, "UVs", "Coordinates")
        source = tex
    else:
        c = list(color or [0.05, 0.05, 0.05])[:3]
        source = g.vector("Color", (c[0], c[1], c[2], 1.0), -600, 0)
    g.out(g.binary("MaterialExpressionMultiply", source, "", strength, "", -200, 100), "", "MP_EMISSIVE_COLOR")
    mel.layout_material_expressions(mat)
    mel.recompile_material(mat)
    unreal.EditorAssetLibrary.save_loaded_asset(mat)
    return mat
